fun toJson(value: Any?, indent: Int = 0): String {
    val sb = StringBuilder()
    writeValue(sb, value, indent, 0)
    return sb.toString()
}

private fun writeValue(sb: StringBuilder, value: Any?, indent: Int, level: Int) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(value.toString())
        is String -> writeString(sb, value)
        is Int -> sb.append(value.toString())
        is Long -> sb.append(value.toString())
        is Double -> {
            if (value.isNaN() || value.isInfinite()) {
                throw IllegalArgumentException("Non-finite double value: $value")
            }
            sb.append(value.toString())
        }
        is Float -> {
            val d = value.toDouble()
            if (d.isNaN() || d.isInfinite()) {
                throw IllegalArgumentException("Non-finite float value: $value")
            }
            sb.append(d.toString())
        }
        is Enum<*> -> writeString(sb, value.name)
        is Map<*, *> -> writeMap(sb, value, indent, level)
        is List<*> -> writeList(sb, value, indent, level)
        is Array<*> -> writeArray(sb, value, indent, level)
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.simpleName}")
    }
}

private fun writeString(sb: StringBuilder, s: String) {
    sb.append('"')
    for (c in s) {
        when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\f' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (c < 0x20) {
                    sb.append("\\u")
                    val hex = c.toString(16)
                    while (hex.length < 4) {
                        sb.append('0')
                    }
                    sb.append(hex)
                } else {
                    sb.append(c)
                }
            }
        }
    }
    sb.append('"')
}

private fun writeMap(sb: StringBuilder, map: Map<*, *>, indent: Int, level: Int) {
    if (map.isEmpty()) {
        sb.append("{}")
        return
    }
    sb.append('{')
    val entries = map.entries.toList()
    for ((i, entry) in entries.withIndex()) {
        if (i > 0) sb.append(',')
        if (indent > 0) {
            sb.append('\n')
            sb.append(" ".repeat((level + 1) * indent))
        }
        val key = entry.key
        if (key !is String) {
            throw IllegalArgumentException("Non-String map key: $key")
        }
        writeString(sb, key)
        if (indent > 0) {
            sb.append(": ")
        } else {
            sb.append(':')
        }
        writeValue(sb, entry.value, indent, level + 1)
    }
    if (indent > 0) {
        sb.append('\n')
        sb.append(" ".repeat(level * indent))
    }
    sb.append('}')
}

private fun writeList(sb: StringBuilder, list: List<*>, indent: Int, level: Int) {
    if (list.isEmpty()) {
        sb.append("[]")
        return
    }
    sb.append('[')
    for ((i, item) in list.withIndex()) {
        if (i > 0) sb.append(',')
        if (indent > 0) {
            sb.append('\n')
            sb.append(" ".repeat((level + 1) * indent))
        }
        writeValue(sb, item, indent, level + 1)
    }
    if (indent > 0) {
        sb.append('\n')
        sb.append(" ".repeat(level * indent))
    }
    sb.append(']')
}

private fun writeArray(sb: StringBuilder, array: Array<*>, indent: Int, level: Int) {
