sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)
fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val n = input.length

    while (i < n) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        // Parentheses
        if (c == '(') {
            tokens.add(Token.Paren(true, i))
            i++
            continue
        }
        if (c == ')') {
            tokens.add(Token.Paren(false, i))
            i++
            continue
        }

        // Strings
        if (c == '"' || c == '\'') {
            val quote = c
            val startPos = i
            i++
            val sb = StringBuilder()
            var terminated = false
            while (i < n) {
                val ch = input[i]
                if (ch == '\\') {
                    if (i + 1 >= n) {
                        throw TokenizeException("Unterminated string", startPos)
                    }
                    val next = input[i + 1]
                    when (next) {
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(next)
                    }
                    i += 2
                } else if (ch == quote) {
                    terminated = true
                    i++
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }
            if (!terminated) {
                throw TokenizeException("Unterminated string", startPos)
            }
            tokens.add(Token.Str(sb.toString(), startPos))
            continue
        }

        // Identifiers
        if (c.isLetter() || c == '_') {
            val startPos = i
            i++
            while (i < n) {
                val ch = input[i]
                if (ch.isLetterOrDigit() || ch == '_' || ch == '.') {
                    i++
                } else {
                    break
                }
            }
            val name = input.substring(startPos, i)
            tokens.add(Token.Ident(name, startPos))
            continue
        }

        // Numbers
        if (c.isDigit()) {
            val startPos = i
            i++
            while (i < n && input[i].isDigit()) {
                i++
            }
            if (i < n && input[i] == '.') {
                i++
                if (i >= n || !input[i].isDigit()) {
                    throw TokenizeException("Malformed number", startPos)
                }
                while (i < n && input[i].isDigit()) {
                    i++
                }
            }
            val numStr = input.substring(startPos, i)
            val value = numStr.toDouble()
            tokens.add(Token.Num(value, startPos))
            continue
        }

        // Negative numbers: '-' followed by digit, only allowed when previous token is absent, Op, or opening Paren
        if (c == '-') {
            if (i + 1 < n && input[i + 1].isDigit()) {
                val lastToken = tokens.lastOrNull()
                val canBeNegative = lastToken == null ||
                        lastToken is Token.Op ||
                        (lastToken is Token.Paren && lastToken.open)
                if (!canBeNegative) {
                    throw TokenizeException("Unexpected '-'", i)
                }
                val startPos = i
                i++ // skip '-'
                while (i < n && input[i].isDigit()) {
                    i++
                }
                if (i < n && input[i] == '.') {
                    i++
                    if (i >= n || !input[i].isDigit()) {
                        throw TokenizeException("Malformed number", startPos)
                    }
                    while (i < n && input[i].isDigit()) {
                        i++
                    }
                }
                val numStr = input.substring(startPos, i)
                val value = numStr.toDouble()
                tokens.add(Token.Num(value, startPos))
                continue
            } else {
                throw TokenizeException("Unexpected character '-'", i)
            }
        }

        // Operators (longest match first)
        if (i + 1 < n) {
            val twoChar = input.substring(i, i + 2)
            if (twoChar == "==" || twoChar == "!=" || twoChar == "<=" || twoChar == ">=" || twoChar == "&&" || twoChar == "||") {
                tokens.add(Token.Op(twoChar, i))
                i += 2
                continue
            }
        }

        // Single character operators
        if (c == '<' || c == '>' || c == '!') {
            tokens.add(Token.Op(c.toString(), i))
            i++
            continue
        }

        // Anything else is an error
        throw TokenizeException("Unexpected character '$c'", i)
    }

    return tokens
}
